package nilepay

import ("bytes"; "context"; "crypto/hmac"; "crypto/sha256"; "crypto/subtle"; "encoding/hex"; "encoding/json"; "fmt"; "io"; "net/http"; "net/url"; "strconv"; "strings"; "time")

type Client struct { APIKey, BaseURL string; HTTPClient *http.Client }
func New(apiKey string) (*Client, error) { if apiKey == "" { return nil, fmt.Errorf("api key is required") }; return &Client{APIKey: apiKey, BaseURL: "https://nilepay-api.runasp.net", HTTPClient: http.DefaultClient}, nil }
func (c *Client) CreateCheckout(ctx context.Context, input any, key string, output any) error { if key == "" { return fmt.Errorf("persist and provide an idempotency key") }; return c.request(ctx, http.MethodPost, "/api/v1/checkout/create", input, key, output) }
func (c *Client) GetCheckout(ctx context.Context, sessionID string, output any) error { return c.request(ctx, http.MethodGet, "/api/v1/checkout/status?sessionId="+url.QueryEscape(sessionID), nil, "", output) }
func (c *Client) request(ctx context.Context, method, path string, body any, key string, output any) error { var reader io.Reader; if body != nil { b, err := json.Marshal(body); if err != nil { return err }; reader = bytes.NewReader(b) }; req, err := http.NewRequestWithContext(ctx, method, strings.TrimRight(c.BaseURL, "/")+path, reader); if err != nil { return err }; req.Header.Set("Authorization", "Bearer "+c.APIKey); req.Header.Set("Content-Type", "application/json"); if key != "" { req.Header.Set("Idempotency-Key", key) }; response, err := c.HTTPClient.Do(req); if err != nil { return err }; defer response.Body.Close(); if response.StatusCode < 200 || response.StatusCode >= 300 { return fmt.Errorf("nilepay API error %s", response.Status) }; return json.NewDecoder(response.Body).Decode(output) }
func VerifyWebhook(raw []byte, eventID, timestamp, signature, secret string, now time.Time) bool { seconds, err := strconv.ParseInt(timestamp, 10, 64); if eventID == "" || err != nil || secret == "" || abs(now.Unix()-seconds) > 300 { return false }; mac := hmac.New(sha256.New, []byte(secret)); mac.Write([]byte(timestamp+".")); mac.Write(raw); expected := mac.Sum(nil); received, err := hex.DecodeString(strings.TrimPrefix(signature, "v1=")); return err == nil && len(expected) == len(received) && subtle.ConstantTimeCompare(expected, received) == 1 }
func abs(v int64) int64 { if v < 0 { return -v }; return v }
